11	impl ChatWidget {
12	    pub(crate) fn set_service_tier(&mut self, service_tier: Option<String>) {
13	        self.config.service_tier = service_tier.clone();
14	        self.effective_service_tier = service_tier;
15	        self.refresh_model_dependent_surfaces();
16	    }
17	
18	    pub(crate) fn current_service_tier(&self) -> Option<&str> {
19	        self.effective_service_tier.as_deref()
20	    }
21	
22	    pub(crate) fn configured_service_tier(&self) -> Option<String> {
23	        self.config.service_tier.clone()
24	    }
25	
26	    pub(crate) fn fast_default_opt_out(&self) -> Option<bool> {
27	        self.config.notices.fast_default_opt_out
28	    }
29	
30	    pub(crate) fn should_show_fast_status(&self, model: &str, service_tier: Option<&str>) -> bool {
31	        service_tier.is_some_and(|service_tier| {
32	            service_tier == ServiceTier::Fast.request_value()
33	                && self.model_supports_service_tier(model, service_tier)
34	        }) && self.has_chatgpt_account
35	    }
36	
37	    pub(super) fn fast_mode_enabled(&self) -> bool {
38	        self.config.features.enabled(Feature::FastMode)
39	    }
40	
41	    pub(crate) fn can_toggle_fast_mode_from_keybinding(&self) -> bool {
42	        self.fast_mode_enabled()
43	            && self.current_model_fast_service_tier().is_some()
44	            && !self.is_user_turn_pending_or_running()
45	            && self.bottom_pane.no_modal_or_popup_active()
46	    }
47	
48	    pub(crate) fn toggle_fast_mode_from_ui(&mut self) {
49	        let Some(fast_tier) = self.current_model_fast_service_tier() else {
50	            return;
51	        };
52	        let next_tier = if self.current_service_tier() == Some(fast_tier.id.as_str()) {
53	            None
54	        } else {
55	            Some(fast_tier.id)
56	        };
57	        self.set_service_tier_selection(next_tier);
58	    }
59	
60	    pub(crate) fn toggle_service_tier_from_ui(&mut self, command: ServiceTierCommand) {
61	        let next_tier = if self.current_service_tier() == Some(command.id.as_str()) {
62	            None
63	        } else {
64	            Some(command.id)
65	        };
66	        self.set_service_tier_selection(next_tier);
67	    }
68	
69	    pub(super) fn sync_service_tier_commands(&mut self) {
70	        self.bottom_pane
71	            .set_service_tier_commands_enabled(self.fast_mode_enabled());
72	        self.bottom_pane
73	            .set_service_tier_commands(self.current_model_service_tier_commands());
74	    }
75	
76	    pub(super) fn current_model_service_tier_commands(&self) -> Vec<ServiceTierCommand> {
77	        let model = self.current_model();
78	        self.model_catalog
79	            .try_list_models()
80	            .ok()
81	            .and_then(|models| {
82	                models
83	                    .into_iter()
84	                    .find(|preset| preset.model == model)
85	                    .map(|preset| {
86	                        preset
87	                            .service_tiers
88	                            .into_iter()
89	                            .map(|tier| ServiceTierCommand {
90	                                id: tier.id,
91	                                name: tier.name.to_lowercase(),
92	                                description: tier.description,
93	                            })
94	                            .collect()
95	                    })
96	            })
97	            .unwrap_or_default()
98	    }
99	
100	    fn set_service_tier_selection(&mut self, service_tier: Option<String>) {
101	        if service_tier.is_none() {
102	            self.config.notices.fast_default_opt_out = Some(true);
103	        }
104	        self.set_service_tier(service_tier.clone());
105	        self.app_event_tx
106	            .send(AppEvent::CodexOp(AppCommand::override_turn_context(
107	                /*cwd*/ None,
108	                /*approval_policy*/ None,
109	                /*approvals_reviewer*/ None,
110	                /*permission_profile*/ None,
111	                /*windows_sandbox_level*/ None,
112	                /*model*/ None,
113	                /*effort*/ None,
114	                /*summary*/ None,
115	                Some(service_tier.clone()),
116	                /*collaboration_mode*/ None,
117	                /*personality*/ None,
118	            )));
119	        self.app_event_tx
120	            .send(AppEvent::PersistServiceTierSelection { service_tier });
121	    }
122	
123	    fn model_supports_service_tier(&self, model: &str, service_tier: &str) -> bool {
124	        self.model_catalog
125	            .try_list_models()
126	            .ok()
127	            .and_then(|models| {
128	                models
129	                    .into_iter()
130	                    .find(|preset| preset.model == model)
131	                    .map(|preset| {
132	                        preset
133	                            .service_tiers
134	                            .iter()
135	                            .any(|tier| tier.id == service_tier)
136	                    })
137	            })
138	            .unwrap_or(false)
139	    }
140	
141	    fn current_model_fast_service_tier(&self) -> Option<ServiceTierCommand> {
142	        self.current_model_service_tier_commands()
143	            .into_iter()
144	            .find(|tier| tier.name.eq_ignore_ascii_case(SPEED_TIER_FAST))
145	    }
146	}
